// Enforce the booking window server-side — never trust the agent to have
// gotten this right on its own. Tue–Fri, 11:00–16:00 IST, 30-minute slots only.
const input = $input.first().json;
const dt = new Date(input.dateTime);

if (isNaN(dt.getTime())) {
  return [{ json: { valid: false, reason: 'dateTime is not a valid date/time.' } }];
}

const day = dt.getDay(); // 0=Sun ... 2=Tue, 3=Wed, 4=Thu, 5=Fri
const hour = dt.getHours();
const minute = dt.getMinutes();
const isWeekday = day >= 2 && day <= 5;
const startsInWindow = (hour > 11 || (hour === 11)) && (hour < 16 || (hour === 16 && minute === 0));
const isHalfHourSlot = minute === 0 || minute === 30;

const valid = isWeekday && startsInWindow && isHalfHourSlot && hour >= 11 && hour < 16;

return [{
  json: {
    valid,
    reason: valid ? '' : 'Appointments are only available Tuesday–Friday, 11:00 AM–4:00 PM, in 30-minute slots.',
    ...input,
  },
}];

